const j = $input.first().json;
if (j.message) {  // Telegram update
  const m = j.message;
  // Private chats only: in a group chat.id is the group, not a client, and the bot must not answer there.
  if (!m.chat || m.chat.type !== 'private') return [];
  return [{ json: { channel: 'tg', contact_id: 'tg:' + m.chat.id, text: (m.text || '').trim(), raw_name: [m.from?.first_name, m.from?.last_name].filter(Boolean).join(' ') } }];
}
// Meta WhatsApp Cloud API (Task 15): the webhook body is entry[0].changes[0].value; the node may hand it over in $json or in $json.body
const meta = (j.entry ? j : (j.body && j.body.entry ? j.body : null));
if (meta) {
  const v = meta.entry?.[0]?.changes?.[0]?.value || {};
  const m = v.messages?.[0];
  if (!m) return [];  // status callback (statuses: sent/delivered/read): start nothing
  return [{ json: { channel: 'wa', contact_id: 'wa:+' + m.from, text: (m.text?.body || '').trim(), raw_name: v.contacts?.[0]?.profile?.name || '' } }];
}
// Unknown channel: end the run; an item with an empty contact_id must never go on.
return [];

const sd = $getWorkflowStaticData('global');
sd.rl = sd.rl || {};
const j = $input.first().json;
const id = j.contact_id, now = Date.now(), WINDOW = 600000, LIMIT = 20;
const hits = (sd.rl[id] || []).filter(t => now - t < WINDOW);
hits.push(now); sd.rl[id] = hits;
if (Object.keys(sd.rl).length > 500) for (const k of Object.keys(sd.rl)) if (!sd.rl[k].some(t => now - t < WINDOW)) delete sd.rl[k];
return [{ json: { ...j, allowed: hits.length <= LIMIT, notify: hits.length === LIMIT + 1 } }];

// Validate first: an empty or malformed contact_id must match NO client row (a comparison with '' would match every row whose column is blank).
const raw = String($('Normalize').first().json.contact_id || '').trim();
const ok = /^(tg:\d{1,20}|wa:\+\d{1,20})$/.test(raw);
const formula = ok
  ? (raw.startsWith('tg:') ? "{telegram_chat_id}='" + raw.slice(3) + "'" : "{phone}='" + raw.slice(3) + "'")
  : "{client_id}='__no_such_client__'";
return [{ json: { formula } }];

const YES = ['yes','yeah','yep','yup','ok','okay','sure','confirm','confirmed','correct','right','да','ага','подтверждаю','ок','давай','хорошо','верно','ja','jawohl','genau','passt','bestätige','bestätigen','sí','si','vale','claro','confirmo','correcto','oui','d\'accord','je confirme','exact','va bene','confermo','sim','так','добре','підтверджую','evet','tamam','onaylıyorum','tak','potwierdzam','oké','prima','نعم','تمام','כן','是','好','确认','はい'];
const NO = ['no','nope','cancel','not now','нет','отмена','не надо','отмени','nein','nee','abbrechen','stornieren','cancelar','cancela','non','annuler','annulla','não','nao','ні','скасувати','hayır','iptal','nie','anuluj','annuleren','لا','לא','不','取消','いいえ'];
const j = $input.first().json;
const raw = (j.text || '').toLowerCase();
const norm = raw.replace(/[^\p{L}\p{N}\s']/gu, ' ').replace(/\s+/g, ' ').trim().replace(/\b(please|пожалуйста|bitte|por favor|s'il vous plaît)\b/g, '').replace(/\s+/g, ' ').trim();
const words = norm ? norm.split(' ') : [];
const is_short = words.length > 0 && words.length <= 3;
let kind = 'other';
if (is_short && YES.includes(norm)) kind = 'yes';
else if (is_short && NO.includes(norm)) kind = 'no';
return [{ json: { ...j, kind, is_short } }];

const c = $('Classify').first().json;
const pending = ($('Pending').first().json.fields || {});
let route = 'reminder';
// A bare YES confirms a waiting proposal. Without one it goes through Reminder Check first: a YES to a reminder must reach
// reminder_reply (CONFIRMED); confirm_booking would answer ALREADY_BOOKED for the reminded visit. Bare Yes? sends it to Confirm afterwards.
if (c.kind === 'yes' && pending.appt_id) route = 'confirm';
else if (pending.appt_id && c.kind === 'other' && c.is_short) route = 'llm';
return [{ json: { route } }];
